class FromRunDouble:
    """Stands in for ReferencePlayer: `from_run` hands out one LoadingAgent per call."""

    def __init__(self) -> None:
        self.calls: list[tuple[RunRecord, str]] = []

    def from_run(self, record: RunRecord, *, team: str = SOLO) -> LoadingAgent:
        self.calls.append((record, team))
        return LoadingAgent()


def test_reference_run_builds_its_player_through_from_run(monkeypatch, tmp_path):
    record = codec.sample("reference.ReferencePlayer", "reference_complete", RunRecord)
    doubles = Doubles(monkeypatch, record)
    reference = FromRunDouble()
    monkeypatch.setattr(players, "ReferencePlayer", reference)

    agents, settings = players.load_player(str(_run_folder(tmp_path, "reference")), 0)

    assert settings == record.settings
    assert reference.calls == [(record, SOLO)]
    assert list(agents) == [SOLO]
    assert agents[SOLO].loaded == []
    assert doubles.made_for == []


